-- Resources content for weather alerts in Log (CLAUDE.md, "Resources stay in step
-- with the code"). Content only; no schema. The Sources guide gains a Weather alerts
-- section and a simpler Weather description; the release note links to it.

select private.rc_release_guide(
  p_slug => 'log-npr-and-weather',
  p_tool_key => 'log',
  p_title => 'Sources: NPR, weather and Florida News Exchange',
  p_summary => 'Check the outside feeds On Air reads: a program''s NPR stories, the current forecast, and stories shared by other Florida stations.',
  p_screen_keys => array['log.sources'],
  p_sort_order => 50,
  p_version_note => 'Added weather alerts',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"text":"The ","type":"text"},{"text":"Sources","type":"text","marks":[{"type":"link","attrs":{"href":"/log/sources"}}]},{"text":" tab holds the outside feeds On Air reads. It opens on one card per source, showing whether its saved data is current, when it was last updated, and what it holds. Select a card's ","type":"text"},{"text":"Open","type":"text","marks":[{"type":"bold"}]},{"text":" button to go to that source's page, and ","type":"text"},{"text":"← Sources","type":"text","marks":[{"type":"bold"}]},{"text":" to come back.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"What the cards say","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Up to date","type":"text","marks":[{"type":"bold"}]},{"text":": the saved data is inside its normal refresh window.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Stale","type":"text","marks":[{"type":"bold"}]},{"text":": the saved data is older than that, or the last refresh failed. What was saved is still shown.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Not fetched yet","type":"text","marks":[{"type":"bold"}]},{"text":": nothing has been read from this source so far.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Not configured","type":"text","marks":[{"type":"bold"}]},{"text":": the portal has no access set up for this source yet.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"NPR","type":"text"}]},{"type":"orderedList","attrs":{"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"On the NPR page, choose a program and a show date, then select ","type":"text"},{"text":"Switch","type":"text","marks":[{"type":"bold"}]},{"text":".","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"The table lists each story's estimated air time (marked with “~”, since NPR doesn't supply exact times), title, teaser, and length.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Select ","type":"text"},{"text":"Refresh","type":"text","marks":[{"type":"bold"}]},{"text":" to pull the latest episode data.","type":"text"}]}]}]},{"type":"paragraph","content":[{"text":"The NPR card reports the most recently read episode. NPR is read one program and date at a time, so it is refreshed from the NPR page rather than the card.","type":"text"}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Weather","type":"text"}]},{"type":"paragraph","content":[{"type":"text","text":"The weather page shows the current forecast as a row of days, with the text for today and tonight under it. Select a day to read its forecast. Select "},{"type":"text","text":"Refresh","marks":[{"type":"bold"}]},{"type":"text","text":" on the page or on the weather card to force an update."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Weather alerts"}]},{"type":"paragraph","content":[{"type":"text","text":"When the National Weather Service has a warning, watch or statement active for Pensacola, a row appears under the forecast. It names the most severe alert and how many more there are. Select the row to see them all, select an alert to read it, and select "},{"type":"text","text":"Full NWS text","marks":[{"type":"bold"}]},{"type":"text","text":" for everything the Weather Service said."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Warnings come first, then watches, then statements."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The same row appears above "},{"type":"text","text":"Full forecast","marks":[{"type":"bold"}]},{"type":"text","text":" in a rundown's Weather panel and on a weather item's card."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Alerts are checked every few minutes. If a check fails, the row shows the last alerts it had, with the time it last checked. If alerts have never been checked, the page says so instead of showing nothing."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Florida News Exchange"}]},{"type":"paragraph","content":[{"type":"text","text":"This page lists the stories other Florida stations shared through PRX in the last 24 hours, newest first. A wrap and its cut are listed together. Each version has a player (its menu has a download option), the feed description, and a link to its page on PRX."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The feed description is often only a summary. The full script can be on the story's PRX page: select "},{"type":"text","text":"Open on PRX","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A hold note from the feed, such as Hold until 10/8, appears beside the story. It is there for you to follow; the portal does not enforce it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Select "},{"type":"text","text":"Add to library","marks":[{"type":"bold"}]},{"type":"text","text":" to open the new content item form with the title, the type News, and a summary already filled in. The summary holds the description, any hold note and the PRX link. Paste the script, save, then add its components (live intro, recorded audio, outro) on the item's page, as for any library item."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Audio is not copied into the portal. Load it into DAD to air it. The links in the feed expire after an hour, so if a player will not play, reload the page."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"text":"Good to know","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"Sources refresh themselves when you open them and their data is past its window. Refresh is a manual option, not something you need to do routinely.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"A fetch failure shows as a plain message, with whatever was last read still on screen. No page goes blank because of a temporary outage.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"text":"NPR's estimated times need a rundown to already exist for that program and date. Without one, the table has nothing to anchor its estimates to.","type":"text"}]}]}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-09-log-weather-alerts',
  p_tool_key => 'log',
  p_released_on => '2026-10-09',
  p_title => 'Weather alerts under the forecast',
  p_guide_slugs => array['log-npr-and-weather'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Active weather alerts now show in a row under the forecast on the Weather page, above "},{"type":"text","text":"Full forecast","marks":[{"type":"bold"}]},{"type":"text","text":" in a rundown's Weather panel, and on a weather item's card. The row names the most severe warning, watch or statement; select it to see the rest and read each one. Alerts recheck every few minutes. The Weather page no longer shows the condensed line or the separate high, low and conditions details."}]}]}$body$
);
